class slider extends common { public static $actions = [ 'config' => self::ROLE_MODERATOR, 'update' => self::ROLE_MODERATOR, 'theme' => self::ROLE_MODERATOR, 'delete' => self::ROLE_MODERATOR, 'index' => self::ROLE_VISITOR ]; const VERSION = '9.0'; const REALNAME = 'Carrousel'; const DELETE = true; const UPDATE = '0.0'; const DATADIRECTORY = ''; public static $directories = []; public static $firstPictures = []; public static $galleries = []; public static $pictures = []; public static $pageList = []; public static $namespace = [ 'white-btns' => 'Blancs', 'centered-btns' => 'Noirs', 'transparent-btns' => 'Bandes invisibles', 'large-btns' => 'Bandes grises', ]; public static $pager = [ true => 'Puces visibles', false => 'Puces invisibles' ]; public static $auto = [ true => 'Active', false => 'Inactive' ]; public static $screenWidth = [ 640 => '640 pixels', 720 => '720 pixels', 768 => '768 pixels', 800 => '800 pixels', 854 => '854 pixels', 1024 => '1024 pixels', 1280 => '1280 pixels', 1400 => '1400 pixels', 1600 => '1600 pixels', 1920 => '1920 pixels', 0 => 'Largeur de l\'écran' ]; public static $selectedMaxwidth = 640; public static $speed = [ '500' => '500 ms', '1000' => '1 s', '1500' => '1.5 s', '2000' => '2 s', '2500' => '2.5 s', '3000' => '3 s', '3500' => '3.5 s' ]; public static $timeout = [ '500' => '500 ms', '1000' => '1 s', '1500' => '1.5 s', '2000' => '2 s', '3000' => '3 s', '5000' => '5 s', '7000' => '7 s', '10000' => '10 s' ]; public static $visibilite_legende = [ 'survol' => 'Au survol', 'toujours' => 'Toujours visible', 'jamais' => 'Jamais visible' ]; public static $position_legende = [ 'haut' => 'En haut', 'bas' => 'En bas' ]; public static $apparition = [ 'opacity 0.2s ease-in' => '0.2s', 'opacity 0.5s ease-in' => '0.5s', 'opacity 1s ease-in' => '1s', 'opacity 2s ease-in' => '2s' ]; public static $sort = [ 'dsc' => 'Alphabétique naturel', 'asc' => 'Alphabétique naturel inverse', 'rand' => 'Aléatoire', 'none' => 'Par défaut, sans tri', ]; public static $caption = [ 'bottom' => 'En bas de l\'image', 'alt' => 'Uniquement dans le texte alternatif' ]; public function update() { if ($this->isPost()) { $this->setData([ 'module', $this->getUrl(0), 'directory', $this->getInput('galleryUpdateDirectory', helper::FILTER_STRING_SHORT, true) ]); $this->addOutput([ 'redirect' => helper::baseUrl() . $this->getUrl(0) . '/config', 'notification' => 'Modifications enregistrées', 'state' => true ]); } self::$directories = $this->getDirectoriesList(); $this->addOutput([ 'title' => 'Configuration de la galerie', 'view' => 'update' ]); } private function getDirectoriesList() { $rootPath = $this->getUserPath($this->getUser('id')); $sharePath = helper::getSubdirectories($rootPath); ksort($sharePath); return array_flip($sharePath); } public function config() { $this->init(); $pagesId = $this->getHierarchy(null, false, null); $excludeBar = $this->getHierarchy(null, false, true); $pagesId = array_diff_key($pagesId, $excludeBar); foreach ($pagesId as $parentKey => $parentValue) { self::$pageList[$parentKey] = $this->getData(['page', $parentKey, 'title']); foreach ($parentValue as $childKey) { self::$pageList[$childKey] = $this->getData(['page', $childKey, 'title']); } } self::$pageList = array_merge([0 => ''], self::$pageList); if ( $this->getUser('permission', __CLASS__, __FUNCTION__) === true && $this->isPost() ) { $inputs['legends'] = $this->getInput('legends', null); $inputs['uri'] = $this->getInput('sliderHref', null); foreach ($inputs as $keyinputs => $valuesinputs) { foreach ($valuesinputs as $keyinput => $valueinput) { $datas[$keyinputs][str_replace('.', '', $keyinput)] = $valueinput; } } $this->setData([ 'module', $this->getUrl(0), [ 'directory' => $this->getData(['module', $this->getUrl(0), 'directory']), 'theme' => $this->getData(['module', $this->getUrl(0), 'theme']), 'legends' => $datas['legends'], 'uri' => $datas['uri'] ] ]); $this->addOutput([ 'redirect' => helper::baseUrl() . $this->getUrl(0) . '/config', 'notification' => 'Modifications enregistrées', 'state' => true ]); } $directory = $this->getData(['module', $this->getUrl(0), 'directory']); if ($directory && is_dir($directory)) { $iterator = new DirectoryIterator($directory); foreach ($iterator as $fileInfos) { if ($fileInfos->isDot() === false and $fileInfos->isFile() and @getimagesize($fileInfos->getPathname())) { $thumbPath = $this->getThumb($fileInfos->getPathname()); if (!file_exists($thumbPath)) { $this->makeThumb( $fileInfos->getPathname(), null, self::THUMBS_WIDTH ); } self::$pictures[$fileInfos->getFilename()] = [ $fileInfos->getFilename(), template::text('legends[' . $fileInfos->getFilename() . ']', [ 'value' => empty($this->getData(['module', $this->getUrl(0), 'legends', str_replace('.', '', $fileInfos->getFilename())])) ? '' : $this->getData(['module', $this->getUrl(0), 'legends', str_replace('.', '', $fileInfos->getFilename())]) ]), template::select('sliderHref[' . $fileInfos->getFilename() . ']', self::$pageList, [ 'selected' => empty($this->getData(['module', $this->getUrl(0), 'uri', str_replace('.', '', $fileInfos->getFilename())])) ? '' : $this->getData(['module', $this->getUrl(0), 'uri', str_replace('.', '', $fileInfos->getFilename())]) ]), '<a href="' . $this->getThumb($fileInfos->getPathname(), '') . '" rel="data-lity" data-lity=""><img src="' . $this->getThumb($fileInfos->getPathname()) . '"></a>' ]; } } switch ($this->getData(['module', $this->getUrl(0), 'theme', 'sort'])) { case 'asc': krsort(self::$pictures, SORT_NATURAL | SORT_FLAG_CASE); break; case 'dsc': ksort(self::$pictures, SORT_NATURAL | SORT_FLAG_CASE); break; case 'rand': $keys = array_keys(self::$pictures); shuffle($keys); $shuffledPictures = []; foreach ($keys as $key) { $shuffledPictures[$key] = self::$pictures[$key]; } self::$pictures = $shuffledPictures; break; case 'none': default: break; } } $this->addOutput([ 'title' => 'Configuration du module', 'view' => 'config' ]); } public function delete() { if ( $this->getUser('permission', __CLASS__, __FUNCTION__) !== true || $this->getData(['module', $this->getUrl(0), $this->getUrl(2)]) === null ) { $this->addOutput([ 'access' => false ]); } else { $this->deleteData(['module', $this->getUrl(0), $this->getUrl(2)]); $this->addOutput([ 'redirect' => helper::baseUrl() . $this->getUrl(0) . '/config', 'notification' => 'Galerie supprimée', 'state' => true ]); } } public function theme() { if ( $this->getUser('permission', __CLASS__, __FUNCTION__) === true && $this->isPost() ) { $speed = $this->getInput('sliderThemespeed', helper::FILTER_INT); $timeout = $this->getInput('sliderThemeDiapoTime', helper::FILTER_INT); if ($speed >= $timeout) { $notification = 'La durée de transition doit inférieure à la durée de l`\'image fixe'; $state = false; } else { $this->setData([ 'module', $this->getUrl(0), [ 'theme' => [ 'pager' => $this->getInput('sliderThemePager', helper::FILTER_BOOLEAN), 'auto' => $this->getInput('sliderThemeAuto', helper::FILTER_BOOLEAN), 'maxWidth' => $this->getInput('sliderThememaxWidth', helper::FILTER_INT), 'speed' => $speed, 'timeout' => $timeout, 'namespace' => $this->getInput('sliderThemeNameSpace', helper::FILTER_STRING_SHORT), 'sort' => $this->getInput('sliderThemeSort', helper::FILTER_STRING_SHORT), 'caption' => $this->getInput('sliderThemeCaption', helper::FILTER_STRING_SHORT), ], 'directory' => $this->getData(['module', $this->getUrl(0), 'directory']), 'legends' => $this->getData(['module', $this->getUrl(0), 'legends']), 'uri' => $this->getData(['module', $this->getUrl(0), 'uri']), ] ]); $notification = 'Modifications enregistrées'; $state = true; } $this->addOutput([ 'redirect' => helper::baseUrl() . $this->getUrl(0) . '/theme', 'notification' => $notification, 'state' => $state ]); } self::$selectedMaxwidth = array_key_exists($this->getData(['module', $this->getUrl(0), 'theme', 'maxWidth']), self::$screenWidth) ? $this->getData(['module', $this->getUrl(0), 'theme', 'maxWidth']) : 640; $this->addOutput([ 'title' => 'Thème', 'view' => 'theme' ]); } public function index() { $galleryId = $this->getUrl(0); $directory = $this->getData(['module', $galleryId, 'directory']); if (is_null($this->getData(['module', $galleryId, 'theme']))) { $this->setData([ 'module', $galleryId, 'theme', [ 'pager' => true, 'auto' => true, 'maxWidth' => 1280, 'speed' => 1000, 'timeout' => 3000, 'namespace' => 'centered-btns', 'sort' => 'dsc', 'caption' => 'bottom' ] ]); } if ($directory && is_dir($directory)) { $iterator = new DirectoryIterator($directory); foreach ($iterator as $fileInfos) { if ($fileInfos->isDot() === false and $fileInfos->isFile() and @getimagesize($fileInfos->getPathname())) { self::$pictures[$directory . '/' . $fileInfos->getFilename()] = [ 'legend' => $this->getData(['module', $galleryId, 'legends', str_replace('.', '', $fileInfos->getFilename())]), 'uri' => $this->getData(['module', $galleryId, 'uri', str_replace('.', '', $fileInfos->getFilename())]) ]; } } switch ($this->getData(['module', $this->getUrl(0), 'theme', 'sort'])) { case 'asc': krsort(self::$pictures, SORT_NATURAL | SORT_FLAG_CASE); break; case 'dsc': ksort(self::$pictures, SORT_NATURAL | SORT_FLAG_CASE); break; case 'rand': $keys = array_keys(self::$pictures); shuffle($keys); $shuffledPictures = []; foreach ($keys as $key) { $shuffledPictures[$key] = self::$pictures[$key]; } self::$pictures = $shuffledPictures; break; case 'none': default: break; } } $this->addOutput([ 'showBarEditButton' => true, 'showPageContent' => true, 'vendor' => [ 'slider' ], 'view' => 'index' ]); } private function scanSubDir($dir) { $dirContent = []; $iterator = new DirectoryIterator($dir); foreach ($iterator as $fileInfos) { if ($fileInfos->isDot() === false and $fileInfos->isDir()) { $dirContent[] = $dir . '/' . $fileInfos->getBasename(); $dirContent = array_merge($dirContent, $this->scanSubDir($dir . '/' . $fileInfos->getBasename())); } } return $dirContent; } private function init() { if (is_null($this->getData(['module', $this->getUrl(0), 'theme']))) { $this->setData([ 'module', $this->getUrl(0), [ 'theme' => [ 'pager' => true, 'auto' => true, 'maxWidth' => '1280', 'speed' => 1000, 'timeout' => 3000, 'namespace' => 'centered-btns', 'sort' => 'RAND', ], 'directory' => null, 'legends' => [], 'uri' => [], ] ]); } } }
